-- Sprint 14 additive migration. Review and apply manually; never auto-apply.
create table public.communication_threads(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),subject text not null,related_type text not null check(related_type in('lead','property','deal','customer','organization')),related_id uuid,status text not null default'open' check(status in('open','waiting_reply','resolved','archived')),unread_count integer not null default 0,last_activity_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.communications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),thread_id uuid not null references public.communication_threads(id),channel text not null check(channel in('whatsapp','email','sms','phone','internal_note','system')),direction text not null check(direction in('inbound','outbound','internal','system')),status text not null,body text not null,user_id uuid references auth.users(id),external_id text,metadata jsonb not null default'{}',occurred_at timestamptz not null default now(),created_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(organization_id,channel,external_id));
create table public.call_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),thread_id uuid references public.communication_threads(id),duration_seconds integer not null check(duration_seconds>=0),outcome text not null,next_follow_up_at timestamptz,lead_id uuid references public.leads(id),deal_id uuid references public.deals(id),occurred_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.follow_ups(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),thread_id uuid references public.communication_threads(id),title text not null,due_at timestamptz not null,status text not null default'pending' check(status in('pending','completed','cancelled')),priority text not null check(priority in('low','medium','high','urgent')),related_type text check(related_type in('lead','property','deal','customer','organization')),related_id uuid,completed_at timestamptz,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,check((related_type is null)=(related_id is null)));
create table public.communication_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),thread_id uuid not null references public.communication_threads(id),body text not null,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.communication_saved_views(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),user_id uuid not null references auth.users(id),name text not null,filters jsonb not null default'{}',created_at timestamptz not null default now(),unique(workspace_id,user_id,name));
create index communication_threads_recent_idx on public.communication_threads(organization_id,workspace_id,last_activity_at desc)where deleted_at is null;create index communications_timeline_idx on public.communications(organization_id,workspace_id,thread_id,occurred_at desc)where deleted_at is null;create index follow_ups_due_idx on public.follow_ups(organization_id,workspace_id,due_at)where deleted_at is null and status='pending';create index call_logs_recent_idx on public.call_logs(organization_id,workspace_id,occurred_at desc)where deleted_at is null;
alter table public.communication_threads enable row level security;alter table public.communications enable row level security;alter table public.call_logs enable row level security;alter table public.follow_ups enable row level security;alter table public.communication_notes enable row level security;alter table public.communication_saved_views enable row level security;
create or replace function public.can_use_communications(p_workspace uuid)returns boolean language sql stable security definer set search_path=public as $$select public.current_workspace_role(p_workspace)in('organization_owner','organization_admin','branch_manager','sales_manager','agent')$$;
create policy "threads_workspace_read" on public.communication_threads for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "communications_workspace_read" on public.communications for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "calls_workspace_read" on public.call_logs for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "followups_workspace_read" on public.follow_ups for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "communication_notes_workspace_read" on public.communication_notes for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "communication_views_owner_read" on public.communication_saved_views for select to authenticated using(user_id=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);
create or replace function public.ensure_communication_thread(p_workspace uuid,p_related_type text,p_related_id uuid,p_subject text)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace and user_id=auth.uid()and status='active';if v_org is null or not can_use_communications(p_workspace)then raise exception'insufficient communication permission';end if;select id into v_id from communication_threads where organization_id=v_org and workspace_id=p_workspace and related_type=p_related_type and related_id is not distinct from p_related_id and deleted_at is null order by created_at limit 1;if v_id is null then insert into communication_threads(organization_id,workspace_id,subject,related_type,related_id,created_by,updated_by)values(v_org,p_workspace,p_subject,p_related_type,p_related_id,auth.uid(),auth.uid())returning id into v_id;end if;return v_id;end$$;
create or replace function public.create_call_log(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_thread uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_use_communications(p_workspace_id)then raise exception'insufficient call permission';end if;v_thread=nullif(p_input->>'threadId','')::uuid;if v_thread is null then v_thread=ensure_communication_thread(p_workspace_id,case when nullif(p_input->>'leadId','')is not null then'lead'else'deal'end,coalesce(nullif(p_input->>'leadId','')::uuid,nullif(p_input->>'dealId','')::uuid),'Call conversation');end if;if not exists(select 1 from communication_threads where id=v_thread and organization_id=v_org and workspace_id=p_workspace_id and deleted_at is null)then raise exception'invalid conversation';end if;insert into call_logs(organization_id,workspace_id,thread_id,duration_seconds,outcome,next_follow_up_at,lead_id,deal_id,created_by,updated_by)values(v_org,p_workspace_id,v_thread,(p_input->>'durationSeconds')::integer,p_input->>'outcome',nullif(p_input->>'nextFollowUpAt','')::timestamptz,nullif(p_input->>'leadId','')::uuid,nullif(p_input->>'dealId','')::uuid,auth.uid(),auth.uid())returning id into v_id;insert into communications(organization_id,workspace_id,thread_id,channel,direction,status,body,user_id)values(v_org,p_workspace_id,v_thread,'phone','outbound','logged',p_input->>'outcome',auth.uid());update communication_threads set last_activity_at=now(),updated_at=now(),updated_by=auth.uid(),version=version+1 where id=v_thread;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'communication.call_logged','Customer call logged',auth.uid(),'call',v_id);if nullif(p_input->>'nextFollowUpAt','')is not null then perform create_follow_up(p_workspace_id,jsonb_build_object('title','Call follow-up','dueAt',p_input->>'nextFollowUpAt','priority','medium','threadId',v_thread));end if;return v_id;end$$;
create or replace function public.create_follow_up(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_use_communications(p_workspace_id)then raise exception'insufficient follow-up permission';end if;insert into follow_ups(organization_id,workspace_id,thread_id,title,due_at,priority,related_type,related_id,created_by,updated_by)values(v_org,p_workspace_id,nullif(p_input->>'threadId','')::uuid,p_input->>'title',(p_input->>'dueAt')::timestamptz,p_input->>'priority',nullif(p_input->>'relatedType',''),nullif(p_input->>'relatedId','')::uuid,auth.uid(),auth.uid())returning id into v_id;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'communication.follow_up_created','Follow-up created',auth.uid(),'follow_up',v_id);return v_id;end$$;
create or replace function public.complete_follow_up(p_follow_up_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare f follow_ups%rowtype;begin select*into f from follow_ups where id=p_follow_up_id and deleted_at is null for update;if not found or not can_use_communications(f.workspace_id)then raise exception'insufficient follow-up permission';end if;if f.version<>p_expected_version then raise exception'follow-up changed by another user';end if;update follow_ups set status='completed',completed_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_follow_up_id;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(f.organization_id,f.workspace_id,'communication.follow_up_completed','Follow-up completed',auth.uid(),'follow_up',f.id);end$$;
create or replace function public.add_communication_note(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare t communication_threads%rowtype;v_id uuid;begin select*into t from communication_threads where id=(p_input->>'threadId')::uuid and deleted_at is null;if not found or not can_use_communications(t.workspace_id)then raise exception'insufficient note permission';end if;insert into communication_notes(organization_id,workspace_id,thread_id,body,created_by,updated_by)values(t.organization_id,t.workspace_id,t.id,p_input->>'body',auth.uid(),auth.uid())returning id into v_id;insert into communications(organization_id,workspace_id,thread_id,channel,direction,status,body,user_id)values(t.organization_id,t.workspace_id,t.id,'internal_note','internal','logged',p_input->>'body',auth.uid());update communication_threads set last_activity_at=now(),updated_at=now(),updated_by=auth.uid(),version=version+1 where id=t.id;return v_id;end$$;
create or replace function public.archive_communication_thread(p_thread_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare t communication_threads%rowtype;begin select*into t from communication_threads where id=p_thread_id and deleted_at is null for update;if not found or not can_use_communications(t.workspace_id)then raise exception'insufficient archive permission';end if;if t.version<>p_expected_version then raise exception'conversation changed by another user';end if;update communication_threads set status='archived',deleted_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_thread_id;end$$;
revoke all on function public.ensure_communication_thread(uuid,text,uuid,text),public.create_call_log(uuid,jsonb),public.create_follow_up(uuid,jsonb),public.complete_follow_up(uuid,integer),public.add_communication_note(jsonb),public.archive_communication_thread(uuid,integer)from public;grant execute on function public.ensure_communication_thread(uuid,text,uuid,text),public.create_call_log(uuid,jsonb),public.create_follow_up(uuid,jsonb),public.complete_follow_up(uuid,integer),public.add_communication_note(jsonb),public.archive_communication_thread(uuid,integer)to authenticated;
